\midrule
\multicolumn{4}{l}{\textit{XNLI Baseline}} \\
EN $\to$ EN & 94.0 & 96.6 & 95.6 \\
ZH $\to$ ZH & 87.5 & 89.5 & 89.0 \\
EN $\to$ ZH & 89.0 & 90.5 & 89.4 \\
